import{L as e,b as t,x as n}from"./vue-DJZSiPbu.js";import{r}from"./app-a38lz1Y_.js";var i=JSON.parse(`{"path":"/read/short/S6.html","title":"『另一道春天的风景线』 | 阅读","lang":"zh-CN","frontmatter":{"title":"『另一道春天的风景线』","reprint":"https://tieba.baidu.com/p/5937728529","description":"30 周年大感谢祭购入特典 中午刚过不久，窗外透进一丝温暖的阳光。 我刚吃饱午饭在窗边昏昏欲睡着，一声巨响传来，把我舒适的睡意全吹走了。 「和真先生，和真先生。我们去赏花吧！樱花非常地漂亮！」 我从情绪高涨的阿库娅身上感到不好的预感，于是决定继续装睡。 「……睡着了吗？喂，和真，其实是醒着的吧？」 就在阿库娅边说边摇着我身子的时候。 「阿库娅，睡着的人...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"『另一道春天的风景线』\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://ajtn123.github.io/konosuba/read/short/S6.html"}],["meta",{"property":"og:site_name","content":"素晴"}],["meta",{"property":"og:title","content":"『另一道春天的风景线』"}],["meta",{"property":"og:description","content":"30 周年大感谢祭购入特典 中午刚过不久，窗外透进一丝温暖的阳光。 我刚吃饱午饭在窗边昏昏欲睡着，一声巨响传来，把我舒适的睡意全吹走了。 「和真先生，和真先生。我们去赏花吧！樱花非常地漂亮！」 我从情绪高涨的阿库娅身上感到不好的预感，于是决定继续装睡。 「……睡着了吗？喂，和真，其实是醒着的吧？」 就在阿库娅边说边摇着我身子的时候。 「阿库娅，睡着的人..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"readingTime":{"minutes":2.24,"words":673},"git":{"createdTime":1784183213000},"autoDesc":true,"filePathRelative":"read/short/S6.md","headers":[]}`),a={name:`S6.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<blockquote><p>30 周年大感谢祭购入特典</p></blockquote><p>中午刚过不久，窗外透进一丝温暖的阳光。</p><p>我刚吃饱午饭在窗边昏昏欲睡着，一声巨响传来，把我舒适的睡意全吹走了。</p><p>「和真先生，和真先生。我们去赏花吧！樱花非常地漂亮！」</p><p>我从情绪高涨的阿库娅身上感到不好的预感，于是决定继续装睡。</p><p>「……睡着了吗？喂，和真，其实是醒着的吧？」</p><p>就在阿库娅边说边摇着我身子的时候。</p><p>「阿库娅，睡着的人被吵醒太可怜了。赏花就我们三个去吧」</p><p>「也对……和真在平日的冒险里也累了吧。就我们三个去算了吧」</p><p>说着些通情达理的话，惠惠和达克尼斯阻止了阿库娅。</p><p>「我还想着越多人赏花越开心的……那就算了吧，好不容易有高级食材当下酒菜呢」</p><p>……高级食材。</p><p>不不不，不要上当了佐藤和真，这个世界的生物基本没有像样的。</p><p>反正就算是樱花，也肯定是那种会突袭过来对着眼睛喷汁然后再来几招飞叶快刀的生物。</p><p>然后阿库娅大哭达克尼斯苦恼着，惠惠来一发爆裂魔法最后我来收拾烂摊子。</p><p>我把高级食材从我的脑子里驱除，维持原样……</p><p>「毕竟樱之精灵是全裸的啊。被兴奋起来的和真骚扰也很棘手，这里就……」</p><p>「喂喂，你们在干嘛。便当带了吗？没有忘记带酒吧？好，那么赶紧出发吧！」</p><p>对着突然起来作出指示的我，三人以一股看垃圾的视线盯着——</p><p>——樱花</p><p>「哇啊啊啊啊啊啊和<sub>真先生！和</sub>真先生！快点救我！！」</p><p>那是只要是日本都会喜爱，告知春天的来访的花。</p><p>「和真，快向树根里撒酒！这样樱之精灵们就会回去地里喝酒了！」</p><p>——樱花</p><p>「你这家伙，我红魔族岂能被区区一植物给瞧不起！拜托帮我争取一下时间！看我用爆裂魔法把你们炸散！！」</p><p>那是只能短暂盛开一周，因此会使人入迷的花。</p><p>「别给我小看日本人！就算硬来我也要一瞧樱之精灵的身姿！」</p><p>我阻止了正准备撒酒的达克尼斯。</p><p>「来正面上我吧啊啊啊啊啊！！」</p><p>我冲进了狂吹的樱花飞舞中————</p><p>此后，就是阿库娅大哭达克尼斯苦恼着惠惠爆裂了，我被要求赔偿樱花树钱的事情了。</p>`,31)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};